export interface StripeLike {
  paymentIntents: {
    create(request: { amount: number; currency: string; capture_method?: string }): Promise<{ id: string }>;
  };
}

export async function createPaymentIntent(stripe: StripeLike, amount: number) {
  if (!Number.isInteger(amount) || amount <= 0) throw new Error('Invalid amount');
  return stripe.paymentIntents.create({
    amount,
    currency: "usd",
    capture_method: "automatic",
  });
}

const { test } = require('node:test');
const { strict: assert } = require('node:assert');
test('payment request specifies capture method required by updated contract', async () => {
  const { createPaymentIntent } = await import('../src/payments.ts');
  let request;
  await createPaymentIntent({ paymentIntents: { create: async value => { request = value; return { id: 'pi_test' }; } } }, 2500);
  assert.equal(request.capture_method, 'automatic');
});
